  ids.forEach((id,i)=>{o['inT_'+id]=d.t[i];o['inS_'+id]=d.s[i];});
  o.inWx=d.inWx;o.inDragonNote=d.inDragonNote;o.inSwingNote=d.inSwingNote;o.inFast=d.inFast;
  ['inSkip','inPrev','inNext','inPause','inPlay'].forEach((k,i)=>o[k]=d.ctl[i]);
  o.inNoMore=d.inNoMore;
  ['inStart','inReplay','inWatch','inTour'].forEach((k,i)=>o[k]=d.btn[i]);
  ['glider','car','bike','walk','dragon','swing'].forEach((id,i)=>o['inTry_'+id]=d.tries[i]);
  for (const id of Object.keys(KEYS)) {
    const kk = id === 'glider' ? KEYS.glider : KEYS[id];
    if (d.k[id].length !== kk.length) throw new Error(l + id);
    o['inK_'+id] = kk.map((k,i)=>k+'|'+d.k[id][i]).join(';');
  }
  ['car','bike','walk'].forEach((id,i)=>o['inTouch_'+id]=d.touch[i]);
  o.inAria=d.inAria; out[l]=o;
}
for (const [l,o] of Object.entries(out)) {
  const f = dir+l+'.json'; const s = fs.readFileSync(f,'utf8');
  const eol = s.includes('\r\n')?'\r\n':'\n';
  const m = s.match(/\s*\}\s*$/); const body = s.slice(0,m.index);
  const endsNl = /\n$/.test(s);
  const add = Object.entries(o).map(([k,v])=>'  '+JSON.stringify(k)+': '+JSON.stringify(v)).join(','+eol);
  fs.writeFileSync(f, body+','+eol+add+eol+'}'+(endsNl?eol:''));
  JSON.parse(fs.readFileSync(f,'utf8'));
}
