.ex-box h2{margin:0 0 16px;font-family:var(--font-display);font-weight:600;font-size:26px;line-height:1.15;color:var(--gold);text-wrap:balance;}
/* Thẻ ảnh (D-044): mỗi chế độ một ảnh chụp từ chính cảnh 3D (public/chooser/*.webp, `npm run gen:chooser`), chữ nằm trên dải tối ở đáy ảnh.
   Máy tính: bốn thẻ dọc 4:5 một hàng + thẻ Tham quan có hướng dẫn thành dải ngang bên dưới. Ảnh chưa tải / lỗi (lớp .ld) thì thẻ còn nền tối + chữ.
   Thẻ vừa chọn (.sel, aria-pressed) giữ viền vàng khi quay lại từ sảnh; ảnh của nó thành dải đầu sảnh (--ex-hero do chooser.ts đặt) */
.ex-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;}
.ex-card{position:relative;isolation:isolate;overflow:hidden;display:flex;flex-direction:column;align-items:flex-start;justify-content:flex-end;gap:4px;aspect-ratio:4/5;min-height:84px;padding:14px;text-align:start;
  background:#0c1418;border:1px solid var(--panel-line);border-radius:10px;transition:transform .35s cubic-bezier(.2,.7,.2,1),border-color .25s,box-shadow .35s;}
.ex-card[data-pick="guided"]{grid-column:1/-1;aspect-ratio:auto;min-height:104px;}
.ex-img{position:absolute;inset:0;z-index:-2;width:100%;height:100%;object-fit:cover;filter:saturate(1.14) contrast(1.05);transition:transform .7s cubic-bezier(.2,.7,.2,1),opacity .4s,filter .3s;}
.ex-img.ld{opacity:0;}
.ex-card::after{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;background:linear-gradient(to top,rgba(6,10,13,.94) 0%,rgba(6,10,13,.62) 30%,rgba(6,10,13,0) 62%);transition:opacity .3s;}
.ex-card[data-pick="guided"]::after{background:linear-gradient(to top,rgba(6,10,13,.9) 0%,rgba(6,10,13,.35) 60%,rgba(6,10,13,.1) 100%);}
.ex-card b{font-family:var(--font-display);font-weight:600;font-size:23px;line-height:1.1;color:#fff;text-shadow:0 1px 8px rgba(0,0,0,.55);}
.ex-card span,.ex-card i{font-style:normal;font-size:12px;line-height:1.4;color:rgba(238,240,234,.86);text-shadow:0 1px 6px rgba(0,0,0,.6);}
@media (hover:hover){
  .ex-card:not(:disabled):hover{transform:translateY(-3px);border-color:var(--gold);box-shadow:0 14px 30px rgba(0,0,0,.45);}
  .ex-card:not(:disabled):hover .ex-img{transform:scale(1.07);}
}
.ex-card:not(:disabled):active{transform:scale(.985);}
.ex-card.sel{border-color:var(--gold);box-shadow:0 0 0 2px var(--gold),0 14px 30px rgba(0,0,0,.45);}
.ex-card.sel b{color:var(--gold);}
.ex-card:disabled{cursor:not-allowed;}
.ex-card:disabled .ex-img{filter:grayscale(.85) brightness(.6);}
.ex-card:disabled b,.ex-card:disabled span{opacity:.7;}
.ex-card:disabled .ex-note{color:var(--gold);}
.ex-card:focus-visible{outline:2px solid rgba(238,240,234,.85);outline-offset:2px;}   /* trắng ngà: khác viền vàng của thẻ đang chọn (.sel) */
.ex-card:focus-visible .ex-img{transform:scale(1.04);}
/* Điện thoại dọc: lưới 2 × 2 thẻ vuông + dải Tham quan; nằm ngang: năm thẻ một hàng */
body.compact .ex-box{padding:16px 14px;}
body.compact .ex-cards{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;}
body.compact .ex-card{aspect-ratio:1/1;padding:11px;}
body.compact .ex-card[data-pick="guided"]{aspect-ratio:auto;min-height:92px;}
body.compact .ex-card b{font-size:19px;}
@media (orientation:landscape){
  body.compact .ex-cards{grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;}
  body.compact .ex-card,body.compact .ex-card[data-pick="guided"]{grid-column:auto;aspect-ratio:4/5;min-height:0;padding:9px;}
  body.compact .ex-card b{font-size:16px;}
  body.compact .ex-card span,body.compact .ex-card i{font-size:10.5px;}
}
