import re
p = 'src/styles/main.css'
s = open(p, encoding='utf-8', newline='').read()
eol = '\r\n' if '\r\n' in s else '\n'

# Phần điện thoại viết một lần với chỗ giữ {S} = tiền tố selector; chèn hai lần (body.compact và @media).
COMPACT = '''{S}#intro{--in-pad:max(16px,env(safe-area-inset-left,0px));--in-foot-h:calc(66px + env(safe-area-inset-bottom,0px));--in-btn:44px;}
{S}#intro::before{backdrop-filter:none;-webkit-backdrop-filter:none;}
{S}#inCap{inset-inline:var(--in-pad);margin-inline:auto;text-align:center;max-width:min(560px,92vw);}
{S}#inEyebrow{justify-content:center;}
{S}#inTitle{font-size:clamp(26px,8vw,40px);}
{S}#inSub{font-size:14.5px;}
{S}#inKeys,{S}#inCap .in-touch{justify-content:center;}
{S}.in-top{top:calc(var(--in-bar) + 8px + env(safe-area-inset-top,0px));}
{S}.in-top button,{S}.in-lang select{min-height:var(--in-btn);}
{S}.in-foot{inset-inline:max(14px,env(safe-area-inset-left,0px)) max(14px,env(safe-area-inset-right,0px));bottom:calc(var(--in-bar) + 8px + env(safe-area-inset-bottom,0px));}
{S}.in-seg{height:30px;}
{S}.in-ctl button{width:var(--in-btn);height:var(--in-btn);}
{S}.in-nomore{min-height:var(--in-btn);}
{S}#intro button,{S}#intro .in-lang select{backdrop-filter:none;-webkit-backdrop-filter:none;}
{S}#inAct,{S}#inStart,{S}.in-modes button,{S}.in-more button{min-height:var(--in-btn);}
{S}#intro[data-scene="finale"]{padding-block:calc(var(--in-bar) + 56px) calc(var(--in-foot-h) + var(--in-bar) + 4px);}
{S}#inStart{width:100%;max-width:340px;}
{S}.in-modes button{flex:1 1 40%;}
'''.replace('\n', eol)

LOW = '''@media (max-height:500px){
  #intro{--in-bar:20px;--in-foot-h:calc(58px + env(safe-area-inset-bottom,0px));}
  #inNote{display:none;}
  #inKeys{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;}
  .in-k{flex:none;}
  #inTitle{font-size:clamp(22px,6vh,32px);}
  #inSub{font-size:13px;}
  #inAct{margin-top:10px;}
  .in-seg{height:24px;}
  .in-ctl{gap:8px;}
  #intro[data-scene="finale"] #inSub{display:none;}
  #intro[data-scene="finale"]{padding-block:calc(var(--in-bar) + 44px) calc(var(--in-foot-h) + var(--in-bar));}
  .in-modes{flex-wrap:nowrap;}
  .in-modes button{flex:1 1 0;padding-inline:8px;}
  #inEnd{margin-top:10px;gap:8px;}
  #inStart{min-height:44px;}
  .in-more{margin-top:0;}
}'''.replace('\n', eol)

CSS = r'''
/* ===== Đoạn giới thiệu (D-045) ===== */
/* Lớp phủ điện ảnh trên canvas (src/intro/ui.ts ghi chữ, tiến trình, nút): dải phim đen trên / dưới, khối chữ góc dưới trái, nút Bỏ qua + ngôn ngữ góc trên phải,
   thanh tiến trình 9 đoạn + điều khiển ở đáy. Cảnh 3D lộ hẳn (không nền); chỉ có một tấm tối rất nhẹ sau chữ cho dễ đọc trên trời sáng.
   Dùng thuộc tính logic (inset-inline…) cho ar RTL; #inVeil là màn tối giữa hai nhịp, JS ghi opacity (không transition). */
#intro{--in-bar:clamp(28px,7vh,64px);--in-pad:clamp(20px,5vw,72px);--in-foot-h:84px;--in-btn:36px;
  position:fixed;inset:0;z-index:21;pointer-events:auto;overflow:hidden;color:var(--text);font-family:var(--font-body);user-select:none;-webkit-user-select:none;}
#intro[hidden]{display:none;}
#intro::before{content:"";position:absolute;inset:0;pointer-events:none;
  background:linear-gradient(to top,rgba(4,8,10,.62) 0%,rgba(4,8,10,.34) 28%,rgba(4,8,10,0) 52%),linear-gradient(to bottom,rgba(4,8,10,.34) 0%,rgba(4,8,10,0) 22%);}
#intro[data-scene="finale"]::before{background:radial-gradient(ellipse 70% 62% at 50% 50%,rgba(4,8,10,.62),rgba(4,8,10,.2) 70%,rgba(4,8,10,.34) 100%);}
#intro > *{position:absolute;}
#intro button,#intro select{font-family:var(--font-body);}
#intro button{-webkit-tap-highlight-color:transparent;}
#intro button:focus-visible,#intro select:focus-visible,.in-nomore input:focus-visible{outline:2px solid var(--gold);outline-offset:2px;}
/* Khi intro chạy: ẩn mọi lớp khác (thắng cả body.explore … {display:block}); thứ nằm trong #intro không có .panel */
body.intro.intro .panel,body.intro.intro #env,body.intro.intro #stHud,body.intro.intro #drHud,body.intro.intro #exChatBtn,body.intro.intro #exChat,
body.intro.intro #exMpLabels,body.intro.intro #hrLabels,body.intro.intro #chooser{display:none!important;}
/* Dải phim */
.in-bar{inset-inline:0;height:var(--in-bar);background:#000;z-index:3;}
.in-bar-t{top:0;animation:inBarT .8s cubic-bezier(.2,.7,.2,1) both;}
.in-bar-b{bottom:0;animation:inBarB .8s cubic-bezier(.2,.7,.2,1) both;}
@keyframes inBarT{from{transform:translateY(-100%);}}
@keyframes inBarB{from{transform:translateY(100%);}}
#inVeil{inset:0;z-index:4;background:#05080a;opacity:0;pointer-events:none;}
/* Góc trên phải: ngôn ngữ + Bỏ qua (dưới dải phim) */
.in-top{z-index:5;top:calc(var(--in-bar) + 12px + env(safe-area-inset-top,0px));inset-inline-end:var(--in-pad);display:flex;align-items:center;gap:10px;}
#inSkip,.in-ctl button,#intro .in-lang select{background:rgba(10,18,22,.55);border:1px solid rgba(255,255,255,.22);color:#fff;
  backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);box-shadow:0 2px 14px rgba(0,0,0,.28);}
#inSkip{height:var(--in-btn);padding:0 18px;border-radius:999px;font-size:12.5px;font-weight:500;letter-spacing:.04em;}
#intro .in-lang select{height:var(--in-btn);border-radius:999px;padding-inline:14px 28px;font-size:12px;max-width:150px;}
#intro .lang::after{inset-inline-end:12px;}
/* Khối chữ: góc dưới trái; mỗi lần đổi nhịp JS gắn lại .in-in để từng dòng trượt lên + hiện dần, so le 70 ms */
#inCap{z-index:5;inset-inline-start:var(--in-pad);bottom:calc(var(--in-bar) + var(--in-foot-h));max-width:min(560px,88vw);text-shadow:0 1px 14px rgba(0,0,0,.55);}
#inEyebrow{display:flex;align-items:center;gap:12px;font:500 11.5px/1.3 var(--font-mono);letter-spacing:.22em;text-transform:uppercase;color:var(--gold);margin-bottom:12px;}
#inEyebrow::before{content:"";flex:none;width:28px;height:1px;background:var(--gold);}
#inTitle{margin:0;font-family:var(--font-display);font-weight:600;font-size:clamp(34px,5.2vw,68px);line-height:1.02;color:#f7f3e6;text-wrap:balance;
  text-shadow:0 2px 26px rgba(0,0,0,.6),0 1px 3px rgba(0,0,0,.45);overflow-wrap:anywhere;}
#inSub{margin:14px 0 0;font-size:clamp(15px,1.25vw,17px);line-height:1.5;color:var(--text);text-wrap:pretty;}
#inNote{margin:8px 0 0;font-size:12px;line-height:1.5;color:var(--muted);}
#inCap.in-in > *{animation:inRise .8s cubic-bezier(.2,.7,.2,1) both;}
#inCap.in-in > :nth-child(2){animation-delay:70ms;}
#inCap.in-in > :nth-child(3){animation-delay:140ms;}
#inCap.in-in > :nth-child(4){animation-delay:210ms;}
#inCap.in-in > :nth-child(5){animation-delay:280ms;}
#inCap.in-in > :nth-child(6){animation-delay:350ms;}
@keyframes inRise{from{opacity:0;transform:translateY(14px);}}
/* Hàng phím / dòng thao tác cảm ứng */
#inKeys{display:flex;flex-wrap:wrap;gap:10px 20px;margin-top:16px;}
.in-k{display:inline-flex;align-items:center;gap:4px;}
.in-k kbd{display:inline-flex;align-items:center;justify-content:center;box-sizing:border-box;height:24px;min-width:24px;padding:0 6px;
  font:500 11px/1 var(--font-mono);color:#fff;background:rgba(10,18,22,.55);border:1px solid rgba(255,255,255,.22);border-radius:5px;
  backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);text-shadow:none;}
.in-k i{font-style:normal;font-size:12px;color:var(--muted);margin-inline-start:6px;text-shadow:0 1px 8px rgba(0,0,0,.7);}
#inCap .in-touch{display:block;font-size:12.5px;line-height:1.5;color:var(--muted);}
/* Nút hành động của nhịp: viên thuốc viền vàng */
#inAct{display:inline-flex;align-items:center;gap:.6em;margin-top:20px;padding:0 22px;height:44px;border-radius:999px;font-size:13.5px;font-weight:500;letter-spacing:.05em;
  color:var(--gold);background:rgba(10,18,22,.4);border:1px solid var(--gold);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);text-shadow:none;transition:background .2s,color .2s,transform .2s;}
#inAct::after{content:"\2192";font-size:1.15em;line-height:1;}
html[dir=rtl] #inAct::after{content:"\2190";}
#inAct:disabled{opacity:.45;cursor:default;}
@media (hover:hover){#inAct:not(:disabled):hover{background:var(--gold);color:#1a1206;transform:translateY(-1px);}
  #inSkip:hover,.in-ctl button:hover{background:rgba(230,189,106,.22);border-color:var(--gold);}}
/* Đáy: tiến trình 9 đoạn + điều khiển, trên dải phim dưới */
.in-foot{z-index:5;inset-inline:var(--in-pad);bottom:calc(var(--in-bar) + 14px + env(safe-area-inset-bottom,0px));display:flex;flex-direction:column;gap:10px;}
#inProg{display:flex;align-items:center;gap:3px;}
#inProg .in-seg{position:relative;flex:1 1 0;min-width:0;height:14px;padding:0;margin:0;border:0;border-radius:0;background:none;box-shadow:none;cursor:pointer;}
#inProg .in-seg.in-ch{margin-inline-start:7px;}   /* đoạn đầu chương: 3 px gap + 7 px = cách 10 px */
#inProg .in-seg::before,#inProg .in-seg i{content:"";position:absolute;inset-inline:0;top:50%;height:3px;margin-top:-1.5px;border-radius:2px;transition:height .15s,margin-top .15s;}
#inProg .in-seg::before{background:rgba(255,255,255,.3);}
#inProg .in-seg i{background:var(--gold);transform:scaleX(var(--f,0));transform-origin:left center;transition:height .15s,margin-top .15s;}
html[dir=rtl] #inProg .in-seg i{transform-origin:right center;}
#inProg .in-seg[aria-current="true"]::before{background:rgba(255,255,255,.5);}
@media (hover:hover){#inProg .in-seg:hover::before,#inProg .in-seg:hover i{height:5px;margin-top:-2.5px;}}
#inProg .in-seg:focus-visible{outline-offset:0;}
.in-ctl{display:flex;align-items:center;gap:10px;}
.in-ctl button{flex:none;display:inline-flex;align-items:center;justify-content:center;width:var(--in-btn);height:var(--in-btn);padding:0;border-radius:50%;font-size:11px;line-height:1;letter-spacing:0;}
.in-nomore{display:inline-flex;align-items:center;gap:8px;margin-inline-start:auto;font-size:12px;color:var(--muted);cursor:pointer;text-shadow:0 1px 8px rgba(0,0,0,.7);}
.in-nomore input{width:16px;height:16px;margin:0;accent-color:var(--gold);cursor:pointer;}
/* Nhịp cuối: chữ ra giữa màn hình, lối vào nằm ngay dưới (tiêu đề + #inEnd xếp theo dòng chảy) */
#intro[data-scene="finale"]{display:flex;flex-direction:column;align-items:center;justify-content:center;
  padding:calc(var(--in-bar) + 56px) var(--in-pad) calc(var(--in-foot-h) + var(--in-bar) + 8px);box-sizing:border-box;}
#intro[data-scene="finale"] > #inCap,#intro[data-scene="finale"] > #inEnd{position:relative;inset:auto;z-index:5;flex:none;}
#intro[data-scene="finale"] > #inCap{max-width:min(780px,92vw);text-align:center;}
#intro[data-scene="finale"] #inEyebrow{justify-content:center;}
#intro[data-scene="finale"] #inEyebrow::after{content:"";flex:none;width:28px;height:1px;background:var(--gold);}
#intro[data-scene="finale"] #inTitle{font-size:clamp(34px,5.6vw,72px);}
#inEnd{display:flex;flex-direction:column;align-items:center;gap:14px;margin-top:26px;width:min(620px,100%);text-shadow:0 1px 10px rgba(0,0,0,.5);}
#inStart{height:52px;padding:0 38px;border-radius:999px;font-size:14px;font-weight:600;letter-spacing:.08em;color:#1a1206;border:1px solid var(--gold);text-shadow:none;
  background:linear-gradient(180deg,var(--gold),var(--gold-deep));box-shadow:0 0 28px rgba(230,189,106,.38),0 6px 18px rgba(0,0,0,.4);transition:transform .2s,box-shadow .2s;}
@media (hover:hover){#inStart:hover{background:linear-gradient(180deg,#f0cb82,var(--gold));transform:translateY(-2px);box-shadow:0 0 36px rgba(230,189,106,.5),0 10px 22px rgba(0,0,0,.4);}}
.in-modes{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;}
.in-modes button{height:var(--in-btn);padding:0 18px;border-radius:999px;font-size:12.5px;color:#fff;background:rgba(10,18,22,.55);border:1px solid rgba(255,255,255,.22);
  backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);text-shadow:none;}
.in-more{display:flex;flex-wrap:wrap;justify-content:center;gap:6px 22px;}
.in-more button{padding:4px 2px;background:none;border:0;border-radius:0;font-size:12.5px;color:var(--text);text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:5px;text-decoration-color:rgba(255,255,255,.38);}
@media (hover:hover){.in-modes button:hover{background:rgba(230,189,106,.22);border-color:var(--gold);}
  .in-more button:hover{background:none;color:var(--gold);text-decoration-color:var(--gold);}}
#inEnd button:disabled{opacity:.45;cursor:default;}
/* Điện thoại: chữ giữa dưới, nút ≥ 44 px, vùng an toàn, bỏ blur (như body.compact .panel) */
@media (max-width:760px),(max-height:500px){
