/* Nút trong màn chọn / bảng Cài đặt */
.ex-intro{display:flex;align-items:center;justify-content:center;gap:8px;margin:14px auto 0;padding:8px 14px;background:none;border:0;color:var(--gold);font-size:13px;letter-spacing:.04em;}
