// Khung thử CSS của intro (Task 3): dựng nội dung giả như Task 4 sẽ làm, chụp ảnh.
import fs from 'node:fs';
import { fileURLToPath, pathToFileURL } from 'node:url';
const ROOT = 'D:/2026 - Tuan/danang-vite/.worktrees/intro-dien-anh/';
const { serveDir, launch, openApp, frames } = await import(pathToFileURL(ROOT + 'tests/lib.mjs').href);
const OUT = ROOT + 'tests/screens/intro-css/';
fs.mkdirSync(OUT, { recursive: true });
const ONLY = process.argv[2] || '';
const srv = await serveDir(ROOT + 'dist/');
const browser = await launch();
const loc = (l) => JSON.parse(fs.readFileSync(ROOT + `src/i18n/locales/${l}.json`, 'utf8'));
const ids = ['welcome', 'glider', 'car', 'bike', 'walk', 'daynight', 'dragon', 'swing', 'finale'];
const chOf = [1, 2, 2, 2, 2, 3, 4, 5, 6];

const VPS = { d: { width: 1280, height: 720 }, m: { width: 390, height: 844, mobile: true }, l: { width: 844, height: 390, mobile: true } };
// [ảnh, viewport, ngôn ngữ, nhịp, đêm?]
const SHOTS = [
  ['d-vi-glider', 'd', 'vi', 'glider', 0], ['d-vi-dragon-night', 'd', 'vi', 'dragon', 1], ['d-vi-finale', 'd', 'vi', 'finale', 0],
  ['d-ar-glider', 'd', 'ar', 'glider', 0], ['d-ar-finale', 'd', 'ar', 'finale', 1], ['d-ru-dragon', 'd', 'ru', 'dragon', 0], ['d-ru-finale', 'd', 'ru', 'finale', 0],
  ['d-ja-car', 'd', 'ja', 'car', 0], ['d-th-swing', 'd', 'th', 'swing', 1], ['d-en-welcome', 'd', 'en', 'welcome', 0],
  ['m-vi-car', 'm', 'vi', 'car', 0], ['m-ru-dragon', 'm', 'ru', 'dragon', 0], ['m-ar-finale', 'm', 'ar', 'finale', 0], ['m-vi-finale', 'm', 'vi', 'finale', 1], ['m-ru-finale', 'm', 'ru', 'finale', 0], ['m-hi-walk', 'm', 'hi', 'walk', 0],
  ['l-vi-car', 'l', 'vi', 'car', 0], ['l-ru-finale', 'l', 'ru', 'finale', 0], ['l-ar-dragon', 'l', 'ar', 'dragon', 1], ['l-vi-finale', 'l', 'vi', 'finale', 0],
].filter((s) => s[0].includes(ONLY));

const pages = {};
for (const [name, vp, lang, scene, night] of SHOTS) {
  if (!pages[vp]) pages[vp] = (await openApp(browser, srv.url, VPS[vp])).page;
  const page = pages[vp];
  const L = loc(lang);
  const touch = vp !== 'd';
  await page.evaluate(([lang, night]) => {
    const sel = document.getElementById('langSelect'); sel.value = lang; sel.dispatchEvent(new Event('change', { bubbles: true }));
    const sl = document.getElementById('timeSlider'); sl.value = night ? '100' : '0'; sl.dispatchEvent(new Event('input', { bubbles: true }));
  }, [lang, night]);
  await frames(page, 30);
  await page.evaluate(({ L, scene, ids, chOf, touch }) => {
    const $ = (id) => document.getElementById(id);
    document.body.classList.add('intro'); $('intro').hidden = false; $('intro').dataset.scene = scene;
    const i = ids.indexOf(scene), ch = chOf[i];
    $('inEyebrow').textContent = `0${ch} · ${L['inCh' + ch]}`;
    $('inTitle').textContent = L['inT_' + scene]; $('inSub').textContent = L['inS_' + scene];
    const note = scene === 'dragon' ? L.inDragonNote : scene === 'swing' ? L.inSwingNote + ' · ' + L.inFast.replace('{n}', 30) : scene === 'daynight' ? L.inWx : '';
    $('inNote').hidden = !note; $('inNote').textContent = note;
    const keys = $('inKeys'); keys.innerHTML = ''; keys.hidden = true;
    const kd = L['inK_' + scene];
    if (kd && ['glider', 'car', 'bike', 'walk'].includes(scene)) {
      keys.hidden = false;
      if (touch && L['inTouch_' + scene]) keys.innerHTML = `<span class="in-touch">${L['inTouch_' + scene]}</span>`;
      else keys.innerHTML = kd.split(';').map((it) => { const [k, m] = it.split('|'); return `<span class="in-k">${k.split(' ').map((x) => `<kbd>${x}</kbd>`).join('')}<i>${m}</i></span>`; }).join('');
    }
    const act = $('inAct'); const tr = L['inTry_' + scene]; act.hidden = !tr || scene === 'finale'; act.textContent = tr || '';
    const prog = $('inProg'); prog.innerHTML = '';
    ids.forEach((id, j) => { const b = document.createElement('button'); b.type = 'button'; b.className = 'in-seg' + ([0, 1, 5, 6, 7, 8].includes(j) ? ' in-ch' : ''); b.innerHTML = `<i style="--f:${j < i ? 1 : j === i ? 0.45 : 0}"></i>`; prog.appendChild(b); });
    $('inEnd').hidden = scene !== 'finale';
    $('inCap').classList.add('in-in');
    $('inLang').innerHTML = `<option>${L._name || 'Lang'}</option>`;
  }, { L, scene, ids, chOf, touch });
  await frames(page, 90);   // qua hoạt cảnh vào
  await page.screenshot({ path: OUT + name + '.png' });
  // đo tràn
  const m = await page.evaluate(() => {
    const vw = innerWidth, vh = innerHeight, bad = [];
    for (const el of document.querySelectorAll('#intro *')) {
      if (!el.checkVisibility || !el.checkVisibility()) continue;
      const b = el.getBoundingClientRect(); if (!b.width || !b.height) continue;
      if (b.left < -0.5 || b.right > vw + 0.5 || b.top < -0.5 || b.bottom > vh + 0.5) bad.push((el.id || el.className || el.tagName) + ' ' + [b.left, b.top, b.right, b.bottom].map((x) => x | 0));
    }
    const r = (s) => { const e = document.querySelector(s); if (!e || !e.checkVisibility()) return null; const b = e.getBoundingClientRect(); return [b.left | 0, b.top | 0, b.right | 0, b.bottom | 0]; };
    return { bad, cap: r('#inCap'), end: r('#inEnd'), foot: r('.in-foot'), top: r('.in-top'), sw: document.documentElement.scrollWidth };
  });
  console.log(name, JSON.stringify(m));
  await page.evaluate(() => { document.body.classList.remove('intro'); document.getElementById('intro').hidden = true; });
}
await browser.close(); srv.close();

